def prompt_cards_from_sarif(sarif):
    cards = []
    for run in sarif.get('runs', []):
        rules = {r['id']: r for r in run.get('tool', {}).get('driver', {}).get('rules', [])}
        tool = run.get('tool', {}).get('driver', {}).get('name')
        for result in run.get('results', []):
            loc = ((result.get('locations') or [{}])[0].get('physicalLocation') or {})
            region = loc.get('region') or {}
            rule = rules.get(result.get('ruleId'), {})
            cards.append({
                'tool': tool,
                'rule_id': result.get('ruleId'),
                'severity': result.get('level') or rule.get('defaultConfiguration', {}).get('level'),
                'path': loc.get('artifactLocation', {}).get('uri'),
                'line': region.get('startLine'),
                'message': result.get('message', {}).get('text'),
                'snippet': (region.get('snippet') or {}).get('text'),
                'help': ((rule.get('help') or {}).get('text') or (rule.get('shortDescription') or {}).get('text')),
                'fingerprints': result.get('partialFingerprints') or result.get('fingerprints') or {},
                'flows': len(result.get('codeFlows') or [])
            })
    return sorted(cards, key=lambda c: (c['severity'] or '', c['path'] or '', c['line'] or 0))
